package com.aitu.lms.visitor;
import com.aitu.lms.domain.*;
public final class WorkloadVisitor implements Visitor<Integer>{ public Integer visitFaculty(Faculty x){int n=0;for(Element e:x.children())n+=e.accept(this);return n;} public Integer visitProgram(Program x){int n=0;for(Element e:x.children())n+=e.accept(this);return n;} public Integer visitCourse(Course x){int n=0;for(Element e:x.children())n+=e.accept(this);return n;} public Integer visitLecture(Lecture x){return x.workload();} public Integer visitLab(Lab x){return x.workload();} public Integer visitExam(Exam x){return x.workload();} public Integer visitStudent(Student x){return 0;} }
